{"code": "import json
import os

# Load and inspect the train.json file
with open("data_small/Annotations/train.json", 'r') as f:
    train_data = json.load(f)

print("Keys in train.json:", train_data.keys())
print("\nType of train.json:", type(train_data))

# Check if it's a list or dict
if isinstance(train_data, list):
    print("Length of train.json:", len(train_data))
    if len(train_data) > 0:
        print("\nFirst entry:")
        print(json.dumps(train_data[0], indent=2))
elif isinstance(train_data, dict):
    for key, value in train_data.items():
        print(f"\n{key}: {type(value)}")
        if isinstance(value, list) and len(value) > 0:
            print(f"  First item: {value[0]}")"}

